<?php
namespace App\Http\Controllers\API\Hub\V1;use App\Http\Controllers\Controller;use Illuminate\Http\Request;
abstract class ApiV1Controller extends Controller{protected function ok(Request$r,mixed$data,int$status=200,array$headers=[]){return response()->json(['data'=>$data,'meta'=>['request_id'=>$r->attributes->get('zigo_request_id')]],$status,$headers);}protected function error(Request$r,string$code,string$message,int$status,array$details=[]){$error=['code'=>$code,'message'=>$message];if($details)$error['details']=$details;return response()->json(['error'=>$error,'meta'=>['request_id'=>$r->attributes->get('zigo_request_id')]],$status);}protected function idempotencyKey(Request$r):?string{$key=$r->header('Idempotency-Key');return is_string($key)&&preg_match('/^[A-Za-z0-9_.:-]{8,160}$/',$key)?$key:null;}protected function idempotentResponse(Request$r,array$result){$body=$result['body'];$body['meta']['request_id']=$r->attributes->get('zigo_request_id');return response()->json($body,$result['status'],$result['replay']?['X-ZIGO-Idempotent-Replay'=>'true']:[]);}}
